using LUMAR_ERP_API_V2.Data;using LUMAR_ERP_API_V2.DTOs.Settings;using Microsoft.Data.SqlClient;namespace LUMAR_ERP_API_V2.Repositories;
public sealed class SettingsRepository(ReadOnlySqlConnectionFactory connections):ISettingsRepository{private const string Safe="LOWER(COALESCE(SettingName,'')) NOT LIKE '%password%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%secret%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%token%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%api%key%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%connection%string%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%jwt%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%scanner%key%' AND LOWER(COALESCE(SettingName,'')) NOT LIKE '%webhook%' AND LOWER(COALESCE(SettingValue,'')) NOT LIKE '%password=%' AND LOWER(COALESCE(SettingValue,'')) NOT LIKE '%server=%'";public Task<IReadOnlyList<SystemSettingListDto>> GetAllAsync(CancellationToken c)=>Q("SELECT SettingID,SettingName,Description FROM dbo.System_Settings WHERE "+Safe+" ORDER BY SettingName,SettingID",null,List,c);public async Task<SystemSettingDetailsDto?> GetByIdAsync(int i,CancellationToken c)=>(await Q("SELECT SettingID,SettingName,SettingValue,Description FROM dbo.System_Settings WHERE SettingID=@id AND "+Safe,i,Detail,c)).FirstOrDefault();public async Task<SystemSettingDetailsDto?> GetByKeyAsync(string k,CancellationToken c)=>(await Q("SELECT SettingID,SettingName,SettingValue,Description FROM dbo.System_Settings WHERE SettingName=@key AND "+Safe,k,Detail,c)).FirstOrDefault();public async Task<IReadOnlyList<SettingCategoryDto>> GetCategoriesAsync(CancellationToken c){var x=await GetAllAsync(c);return x.GroupBy(v=>Category(v.SettingName)).OrderBy(v=>v.Key).Select(v=>new SettingCategoryDto(v.Key,v.Count())).ToList();}public async Task<IReadOnlyList<SystemSettingListDto>> GetByCategoryAsync(string category,CancellationToken c)=>(await GetAllAsync(c)).Where(v=>string.Equals(Category(v.SettingName),category,StringComparison.OrdinalIgnoreCase)).ToList();private static string Category(string? key){var n=key?.IndexOf('.')??-1;return n>0?key![..n]:"General";}private static SystemSettingListDto List(SqlDataReader r)=>new(r.GetInt32(0),r.NullableString("SettingName"),Category(r.NullableString("SettingName")),r.NullableString("Description"));private static SystemSettingDetailsDto Detail(SqlDataReader r)=>new(r.GetInt32(0),r.NullableString("SettingName"),r.NullableString("SettingValue"),Category(r.NullableString("SettingName")),r.NullableString("Description"));private async Task<IReadOnlyList<T>> Q<T>(string sql,object? parameter,Func<SqlDataReader,T> map,CancellationToken ct){await using var c=connections.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand(sql,c);if(parameter is int id)cmd.Parameters.AddWithValue("@id",id);else if(parameter is string key)cmd.Parameters.AddWithValue("@key",key);await using var r=await cmd.ExecuteReaderAsync(ct);var x=new List<T>();while(await r.ReadAsync(ct))x.Add(map(r));return x;}}